    H, W = len(grid), len(grid[0])
    bg = max(set(v for r in grid for v in r), key=lambda v: sum(x == v for r in grid for x in r))
    singles = [(r, c, grid[r][c]) for r in range(H) for c in range(W)
               if grid[r][c] != bg and sum(grid[x][y] == grid[r][c]
                   for x in range(H) for y in range(W)) == 2]
    color = singles[0][2]
    starts = [(r, c) for r, c, _ in singles]
    stops = []
    for r in range(H):
        colors = set(grid[r]) - {bg}
        for marker in colors:
            cols = [c for c in range(W) if grid[r][c] == marker]
            if len(cols) == 3:
                other = colors - {marker}
                if len(other) == 1 and len(grid[r]) - len(cols) == sum(grid[r][c] == next(iter(other)) for c in range(W)):
                    stops.append((r, cols[1]))
    route = [starts[0]] + stops + [starts[1]]
    stopset = set(stops)
    for (r0, c0), (r1, c1) in zip(route, route[1:]):
        dr = 1 if r1 > r0 else -1
        for r in range(r0, r1, dr):
            if grid[r][c0] == bg or (r, c0) in stopset:
                out[r][c0] = color
        tr = r1 - dr
        dc = 1 if c1 > c0 else -1
        for c in range(c0, c1 + dc, dc):
            if grid[tr][c] == bg or (tr, c) in stopset:
                out[tr][c] = color
        if grid[r1][c1] == bg or (r1, c1) in stopset:
            out[r1][c1] = color
    return out
